import{_ as e,o,c as a,ai as r}from"./chunks/framework.C33Uq6m-.js";const u=JSON.parse('{"title":"Protocol Observatory","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/protocols.md","filePath":"en/guide/protocols.md"}'),s={name:"en/guide/protocols.md"};function n(l,t,d,i,c,h){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="protocol-observatory" tabindex="-1">Protocol Observatory <a class="header-anchor" href="#protocol-observatory" aria-label="Permalink to &quot;Protocol Observatory&quot;">​</a></h1><p>The <strong>Protocol Observatory</strong> fires the same prompt through <strong>three different serving protocols</strong> against your local Ollama daemon, in parallel, and shows you exactly how each one frames the same conversation.</p><p><strong>Sidebar item:</strong> Protocol Observatory (under Code Completion) <strong>Route:</strong> <code>/protocols</code><strong>Added in:</strong> v0.4.7 (May 2026)</p><h2 id="what-s-the-point" tabindex="-1">What&#39;s the point? <a class="header-anchor" href="#what-s-the-point" aria-label="Permalink to &quot;What&#39;s the point?&quot;">​</a></h2><p>Ollama doesn&#39;t speak just one protocol. It actually exposes the same local model through three different wire formats:</p><table tabindex="0"><thead><tr><th>Endpoint</th><th>Format</th><th>Stream framing</th></tr></thead><tbody><tr><td><code>/api/chat</code></td><td>Ollama-native</td><td>NDJSON (one JSON per line)</td></tr><tr><td><code>/v1/chat/completions</code></td><td>OpenAI-compatible</td><td>SSE (<code>data: …</code>)</td></tr><tr><td><code>/v1/messages</code></td><td>Anthropic-compatible</td><td>SSE with <code>event:</code> tags</td></tr></tbody></table><p>Different ecosystems talk to LLMs through different protocols. If you&#39;re building integrations, debugging a client library, or just curious about how the same model behaves under different framings, this page makes the differences visible — <strong>all against the same local model, with no cloud, no API keys, and no signup.</strong></p><h2 id="using-the-page" tabindex="-1">Using the page <a class="header-anchor" href="#using-the-page" aria-label="Permalink to &quot;Using the page&quot;">​</a></h2><ol><li>Pick a model from the dropdown.</li><li>Type a prompt (a default is provided).</li><li>Adjust max tokens if needed.</li><li>Click <strong>Run all 3 protocols</strong>.</li></ol><p>Three columns stream their responses in parallel. Each column shows:</p><ul><li>The <strong>protocol name</strong> and endpoint path</li><li>A live <strong>status badge</strong> (idle → streaming → completed)</li><li>The <strong>streaming response text</strong></li><li>A <strong>metrics grid</strong>: TTFT, total ms, tokens, tokens/sec, finish reason</li><li>An expandable <strong>Inspect envelope</strong> panel showing the raw first and final chunks/events</li></ul><h2 id="the-envelope-diff-tab" tabindex="-1">The Envelope Diff tab <a class="header-anchor" href="#the-envelope-diff-tab" aria-label="Permalink to &quot;The Envelope Diff tab&quot;">​</a></h2><p>Once all three runs complete, a tabbed lower section appears. Switch to <strong>Envelope diff</strong> to see a side-by-side comparison of how each protocol frames its responses:</p><table tabindex="0"><thead><tr><th>Aspect</th><th>Native</th><th>OpenAI-compat</th><th>Anthropic-compat</th></tr></thead><tbody><tr><td>Stream framing</td><td>NDJSON</td><td>SSE</td><td>SSE with <code>event:</code> tags</td></tr><tr><td>Finish-reason carrier</td><td><code>done</code> + <code>done_reason</code></td><td><code>choices[].finish_reason</code></td><td><code>message_stop</code> event</td></tr><tr><td>Token-count carrier</td><td><code>eval_count</code> + <code>prompt_eval_count</code></td><td><code>usage.{prompt,completion,total}_tokens</code></td><td><code>usage.{input,output}_tokens</code></td></tr><tr><td>Error envelope</td><td><code>{&quot;error&quot;: &quot;string&quot;}</code></td><td><code>{&quot;error&quot;: {&quot;message&quot;, &quot;type&quot;, &quot;code&quot;}}</code></td><td><code>{&quot;type&quot;: &quot;error&quot;, &quot;error&quot;: {...}, &quot;request_id&quot;}</code></td></tr></tbody></table><p>The &quot;this run&quot; rows fill in with the actual values observed during your run — so you can see, for example, that the native protocol returned <code>done_reason: &quot;stop&quot;</code> while the Anthropic protocol called the same outcome <code>stop_reason: &quot;end_turn&quot;</code>.</p><h2 id="why-three-protocols" tabindex="-1">Why three protocols? <a class="header-anchor" href="#why-three-protocols" aria-label="Permalink to &quot;Why three protocols?&quot;">​</a></h2><p>This isn&#39;t theoretical — many real tools rely on these compatibility layers:</p><ul><li><strong>OpenAI-compat</strong> is how IDE plugins, Cursor, Continue.dev, and most Python libraries that expect &quot;the OpenAI API&quot; talk to local models.</li><li><strong>Anthropic-compat</strong> is how tools like Claude Code, Claude Cowork, and OpenClaw talk to Ollama (added in Ollama v0.23 / January 2026).</li><li><strong>Native</strong> is what gives you the richest metrics — including timings, evaluation counts, and the <code>done_reason</code> field.</li></ul><p>If a third-party tool acts strangely against your local Ollama, the Protocol Observatory lets you see what the wire actually looks like through that protocol&#39;s lens.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./chat-diagnostics.html">Chat Diagnostics</a> for single-protocol deep analysis</li><li><a href="./compare.html">Compare</a> for comparing different <em>models</em> against the same prompt (the Protocol Observatory keeps the model constant and varies the protocol)</li></ul>',21)])])}const m=e(s,[["render",n]]);export{u as __pageData,m as default};
